[154,"Thời hiệu yêu cầu Tòa án giải tranh chấp lao động tập thể về quyền là bao nhiêu lâu?",["18 tháng, kể từ ngày xảy ra hành vi mà mỗi bên tranh chấp cho rằng quyền, lợi ích của mình bị vi phạm.","12 tháng, kể từ ngày phát hiện ra hành vi mà bên tranh chấp cho rằng quyền, lợi ích hợp pháp của mình bị vi phạm.","Hai năm, kể từ ngày xảy ra hành vi mà mỗi bên tranh chấp cho rằng quyền, lợi ích của mình bị vi phạm.","Ba năm, kể từ ngày xảy ra hành vi mà mỗi bên tranh chấp cho rằng quyền, lợi ích của mình bị vi phạm."],1],
[155,"Tổ chức đại diện người lao động tổ chức và lãnh đạo đình công bắt đầu từ khi nào?",["Ngay sau khi quyết định đình công và thông báo về thời điểm bắt đầu đình công được gửi cho bên liên quan.","Đến thời điểm bắt đầu đình công, nếu người sử dụng lao động vẫn không chấp nhận giải quyết yêu cầu của người lao động.","Từ khi người sử dụng lao động, Ủy ban nhân dân cấp huyện và cơ quan chuyên môn về lao động thuộc Ủy ban nhân dân cấp tỉnh nhận được quyết định đình công.","Bất kỳ khi nào mà tổ chức đại diện người lao động tổ chức và lãnh đạo đình công thấy phù hợp."],1],
[156,"Tổ chức đại diện người lao động tổ chức và lãnh đạo đình công phải gửi văn bản về việc quyết định đình công cho cơ quan, tổ chức nào?",["Hòa giải viên lao động và cơ quan chuyên môn về lao động thuộc Ủy ban nhân dân cấp tỉnh.","Ủy ban nhân dân cấp huyện và cơ quan chuyên môn về lao động thuộc Ủy ban nhân dân cấp tỉnh.","Người sử dụng lao động, Ủy ban nhân dân cấp huyện và cơ quan chuyên môn về lao động thuộc Ủy ban nhân dân cấp tỉnh.","Tòa án nhân dân và Hội đồng trọng tài lao động."],2],
[157,"Tranh chấp lao động cá nhân là tranh chấp?",["Giữa người lao động với người lao động.","Giữa người lao động với người sử dụng lao động.","Giữa tập thể người lao động với người sử dụng lao động.","Giữa công đoàn với người sử dụng lao động"],1],
[158,"Tranh chấp nào sau đây là tranh chấp lao động tập thể về lợi ích?",["Khi một bên từ chối thương lượng hoặc không tiến hành thương lượng trong thời hạn theo quy định của pháp luật.","Có sự khác nhau trong việc hiểu và thực hiện quy định của thỏa ước lao động tập thể, nội quy lao động, quy chế và thỏa thuận hợp pháp khác;","Có sự khác nhau trong việc hiểu và thực hiện quy định của pháp luật về lao động;","Khi người sử dụng lao động có hành vi phân biệt đối xử đối với người lao động, thành viên ban lãnh đạo của tổ chức đại diện người lao động vì lý do thành lập, gia nhập, hoạt động trong tổ chức đại diện người lao động; can thiệp, thao túng tổ chức đại diện người lao động; vi phạm nghĩa vụ về thương lượng thiện chí."],0],
[159,"Tranh chấp nào sau đây thuộc thẩm quyền giải quyết của tòa án nhân dân cấp huyện?",["Tranh chấp lao động cá nhân không có yếu tố nước ngoài.","Tranh chấp lao động cá nhân có yếu tố nước ngoài.","Tranh chấp lao động tập thể không có yếu tố nước ngoài.","Tranh chấp lao động tập thể có yếu tố nước ngoài."],0],
[160,"Trình tự đình công như thế nào?",["Lấy ý kiến về đình công; Thông báo đình công và tiến hành đình công.","Lấy ý kiến về đình công; Ra quyết định đình công và thông báo đình công; Tiến hành đình công.","Ra quyết định đình công, thông báo đình công; Tiến hành đình công.","Lấy ý kiến về đình công; Tiến hành đình công."],1],
[161,"Trình tự, thủ tục giải quyết tranh chấp lao động tập thể về quyền như thế nào?",["Hoà giải viên lao động tiến hành hòa giải trước, nếu hoà giải không thành thì mỗi bên có quyền yêu cầu Hội đồng trọng tài lao động giải quyết. Ban trọng tài lao động được thành lập để giải quyết vụ tranh chấp, nếu một trong các bên không thi hành quyết định giải quyết tranh chấp của Ban trọng tài lao động thì có quyền yêu cầu Tòa án giải quyết.","Hoà giải viên lao động tiến hành hòa giải trước, nếu hoà giải không thành thì các bên chỉ có quyền yêu cầu Tòa án giải quyết.","Hoà giải viên lao động tiến hành hòa giải trước, nếu hoà giải không thành thì các bên có quyền đình công","Hoà giải lao động tiến hành giải quyết tranh chấp, nếu các bên không đồng ý với quyết định của hoà giải viên lao động thì các bên có quyền yêu cầu Hội đồng trọng tài lao động giải quyết hoặc đình công"],0],
[162,"Trình tự, thủ tục hòa giải tranh chấp lao động cá nhân như thế nào?",["Hoà giải viên lao động tiến hành hòa giải, nếu hoà giải không thành thì người lao động có quyền đình công hoặc khởi kiện ra Tòa án yêu cầu giải quyết tranh chấp.","Các bên tranh chấp khởi kiện ra Toà án, Toà án giải quyết tranh chấp theo thủ tục tố tụng dân sự.","Hoà giải viên lao động tiến hành hòa giải, nếu hoà giải không thành thì phải chuyển cho Hội đồng trọng tài lao động cấp tỉnh giải quyết","Hoà giải viên lao động hướng dẫn, hỗ trợ các bên thương lượng hòa giải, nếu hoà giải không thành thì mỗi bên tranh chấp có yêu cầu Hội đồng trọng tài lao động hoặc Toà án giải quyết, trừ một số tranh chấp pháp luật quy định."],3],
[163,"Tổ chức đại diện người lao động tổ chức và lãnh đạo đình công phải gửi văn bản về việc quyết định đình công cho người sử dụng lao động, Ủy ban nhân dân cấp huyện và cơ quan chuyên môn về lao động thuộc Ủy ban nhân dân cấp tỉnh trong thời gian ít nhất là bao nhiêu ngày",["5 ngày làm việc","5 ngày","10 ngày làm việc","10 ngày"],0],
[164,"Trường hợp do sự kiện bất khả kháng, trở ngại khách quan thì thời hiệu yêu cầu giải quyết tranh chấp lao động cá nhân được tính như thế nào?",["Người yêu cầu chứng minh được vì sự kiện bất khả kháng, trở ngại khách quan đó không tính vào thời hiệu yêu cầu giải quyết tranh chấp lao động.","Được kéo dài đến 03 tháng, kể từ ngày xảy ra sự kiện bất khả kháng, trở ngại khách quan.","Được kéo dài đến 06 tháng, kể từ ngày xảy ra sự kiện bất khả kháng, trở ngại khách quan","Được kéo dài đến 12 tháng, kể từ ngày xảy ra sự kiện bất khả kháng, trở ngại khách quan."],1],
[165,"Trường hợp một trong các bên không thi hành quyết định giải quyết tranh chấp của Ban trọng tài lao động thì các bên có quyền yêu cầu cơ quan nào tiếp tục giải quyết?",["Ủy ban nhân dân huyện giải quyết.","Thanh tra lao động giải quyết.","Tòa án giải quyết.","Hòa giải viên lao động giải quyết."],2],
[166,"Trường hợp nào tổ chức đại diện người lao động là bên tranh chấp không được tiến hành thủ tục đình công?",["Người sử dụng lao động là bên tranh chấp không thực hiện quyết định giải quyết tranh chấp của Ban trọng tài lao động.","Ban trọng tài lao động không được thành lập trong thời hạn 07 ngày làm việc kể từ ngày nhận được yêu cầu giải quyết tranh chấp.","Ban trọng tài lao động không tiến hành giải quyết tranh chấp lao động, không ra quyết định về việc giải quyết tranh chấp, không gửi cho các bên quyết định giải quyết tranh chấp trong thời gian luật định.","Hội đồng trọng tài lao động đang tiến hành giải quyết tranh chấp."],3],
[167,"Việc tổ chức lấy ý kiến đình công thực hiện khi nào?",["Khi xảy ra nguy cơ gây thiệt hại nghiêm trọng, đe dọa sức khỏe của con người.","Trước khi tiến hành đình công.","Trong thời gian cơ quan, tổ chức, cá nhân giải quyết tranh chấp.","Sau khi có quyết định hoãn đình công."],-1,{"k":"unk","t":"File gốc tô đỏ cả 2 lựa chọn đầu nên không rõ đáp án đúng."}],
[168,"Cơ quan nào có chịu trách nhiệm cao nhất trong việc thực hiện quản lý nhà nước về lao động?",["Ủy ban nhân dân cấp tỉnh.","Bộ Lao động - Thương binh và Xã hội","Ủy ban nhân dân cấp huyện.","Sở Lao động - Thương binh và Xã hội."],1],
[169,"Hình thức xử phạt người có hành vi vi phạm quy định của pháp luật về lao động là gì?",["Phạt tiền, đình chỉ thu hồi giấy phép, buộc bồi thường, đóng cửa doanh nghiệp, khiển trách.","Cảnh cáo; phạt tiền; đình chỉ, tước quyền sử dụng giấy phép hoạt động, chứng chỉ nghề có thời hạn;","Cảnh cáo, phạt tiền, đình chỉ thu hồi giấy phép, đóng cửa doanh nghiệp.","Đình chỉ thu hồi giấy phép, đóng cửa doanh nghiệp, cảnh cáo, khiển trách, phạt tiền."],1],
[170,"Khi đã có quyết định của Tòa án về cuộc đình công là bất hợp pháp mà người lao động không ngừng đình công, không trở lại làm việc thì có thể phải chịu trách nhiệm gì?",["Trách nhiệm hình sự.","Trách nhiệm hành chính","Trách nhiệm kỷ luật.","Trách nhiệm bồi thường."],1],
[171,"Nội dung nào không thuộc nhiệm vụ quản lý nhà nước về lao động?",["Quyết định chính sách tiền lương đối với người lao động.","Giáo dục nghề nghiệp, phát triển kỹ năng nghề.","Kiểm tra, thanh tra, xử lý vi phạm pháp luật về lao động","Giải quyết đơn khởi kiện yêu cầu tranh chấp lao động."],1],
[172,"Trách nhiệm thực hiện quản lý nhà nước về lao động ở địa phương thuộc về cơ quan nào?",["Bộ Lao động - Thương binh và Xã hội.","Tổ chức đại diện của người lao động.","Ủy ban nhân dân các cấp","Tổ chức đại điện của người sử dụng lao động."],2],
[173,"Trường hợp đình công gây thiệt hại cho người sử dụng lao động và Tòa án tuyên bố cuộc đình công là bất hợp pháp thì trách nhiệm bồi thường thuộc về cơ quan, tổ chức nào?",["Tổ chức đại diện người lao động tổ chức và lãnh đạo đình công phải bồi thường thiệt hại theo quy định của pháp luật.","Tổ chức đại diện người sử dụng lao động tổ chức và tổ chức của người lãnh đạo đình công phải bồi thường thiệt hại theo quy định của pháp luật.","Tập thể người lao động tại nơi xảy ra đình công phải bồi thường thiệt hại theo quy định của pháp luật.","Tổ chức của người lao động phải bồi thường thiệt hại theo quy định của pháp luật."],2]
